import sys
import heapq

def minimumCostPath(grid):
    n = len(grid)
    if n == 0:
        return 0

    # Distance matrix initialized to infinity
    dist = [[float('inf')] * n for _ in range(n)]
    dist[0][0] = grid[0][0]

    # Priority queue: (cost, row, col)
    pq = [(grid[0][0], 0, 0)]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while pq:
        cost, r, c = heapq.heappop(pq)

        # If we reached the bottom-right cell
        if r == n - 1 and c == n - 1:
            return cost

        # Skip if we found a better path already
        if cost > dist[r][c]:
            continue

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < n:
                new_cost = cost + grid[nr][nc]
                if new_cost < dist[nr][nc]:
                    dist[nr][nc] = new_cost
                    heapq.heappush(pq, (new_cost, nr, nc))

    return dist[n-1][n-1]

def main():
    try:
        data = sys.stdin.read().split()
    except Exception:
        return

    if not data:
        return

    iterator = iter(data)
    try:
        n = int(next(iterator))
        grid = []
        for _ in range(n):
            row = []
            for _ in range(n):
                row.append(int(next(iterator)))
            grid.append(row)

        result = minimumCostPath(grid)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
